<script setup>
const{data,refresh}=await useFetch('/api/products?all=true');const products=computed(()=>data.value?.products||[]);const open=ref(false);const form=reactive({name:'',category:'Treat',skin:'All skin',price:32,benefit:'',ingredient:'',shade:'rose',published:true});
async function add(){await $fetch('/api/products',{method:'POST',body:form});open.value=false;Object.assign(form,{name:'',category:'Treat',skin:'All skin',price:32,benefit:'',ingredient:'',shade:'rose',published:true});await refresh()}async function toggle(p){await $fetch(`/api/products/${p.id}`,{method:'PATCH'});await refresh()}
</script>
<template><main class="admin"><aside class="admin-side glass"><NuxtLink class="brand" to="/"><i>l</i>LumaSkin</NuxtLink><nav><a class="active">▦ Products</a><a>◇ Orders <span>12</span></a><a>◎ Customers</a><a>⌁ Journal</a></nav><NuxtLink to="/">← Back to store</NuxtLink></aside><section class="admin-main"><header><div><p>CATALOG</p><h1>Products</h1><span>Manage the sample storefront catalog.</span></div><button class="primary" @click="open=true">+ Add product</button></header><div class="admin-stats"><article class="glass"><span>ACTIVE PRODUCTS</span><b>{{products.filter(p=>p.published).length}}</b><small>currently visible</small></article><article class="glass"><span>COLLECTIONS</span><b>4</b><small>routine categories</small></article><article class="glass"><span>LOW STOCK</span><b>2</b><small>sample alert</small></article></div><div class="table-wrap glass"><div class="table-tools"><input placeholder="Search products"><button>Filter⌄</button></div><table><thead><tr><th>PRODUCT</th><th>CATEGORY</th><th>PRICE</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody><tr v-for="p in products" :key="p.id"><td><div :class="['tiny',p.shade]">{{p.icon}}</div><span><b>{{p.name}}</b><small>{{p.ingredient}}</small></span></td><td>{{p.category}}</td><td>${{p.price}}</td><td><i :class="p.published?'live':'draft'">{{p.published?'Published':'Hidden'}}</i></td><td><button @click="toggle(p)">{{p.published?'Hide':'Publish'}}</button></td></tr></tbody></table></div></section><div v-if="open" class="overlay" @click="open=false"></div><div v-if="open" class="admin-modal glass"><button class="x" @click="open=false">×</button><p class="eyebrow">NEW PRODUCT</p><h2>Add to catalog</h2><div class="form-grid"><label>Product name<input v-model="form.name" placeholder="e.g. Moon Milk Essence"></label><label>Category<select v-model="form.category"><option>Cleanse</option><option>Treat</option><option>Moisturize</option><option>Protect</option></select></label><label>Skin note<input v-model="form.skin"></label><label>Price<input v-model="form.price" type="number"></label></div><label>Benefit<textarea v-model="form.benefit"></textarea></label><label>Hero ingredient<input v-model="form.ingredient"></label><button class="primary full" :disabled="!form.name" @click="add">Save sample product</button></div></main></template>
